//! Extra menu (Interface > Show 'Extra' menus, /GUI/ShowExtraMenus), item for item as Audacity 3.7.3
//! lists it with that preference on (GetInfo: Type=Menus; generated by tools/compare_prefs.py data).

/// One Extra-menu entry: a submenu header (`id` empty, depth 1), a separator, or a command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ExtraItem {
    /// Nesting depth below the Extra menu (1 = submenu or top item, 2 = inside a submenu).
    pub depth: u8,
    /// Menu label (English; translated at display).
    pub label: &'static str,
    /// Audacity command id; empty for submenus and separators.
    pub id: &'static str,
}

